const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhan = ee.Geometry.Point([114.305, 30.593]).buffer(20000); // 20km buffer around Wuhan
  const startDate2019 = '2019-02-01';
  const endDate2019 = '2019-02-28';
  const startDate2020 = '2020-02-01';
  const endDate2020 = '2020-02-29'; // 2020 is a leap year

  // There is no direct PM2.5 dataset. We use Aerosol Optical Depth (AOD) as a proxy,
  // as it is highly correlated with PM2.5 concentration.
  // The MODIS MCD19A2_GRANULES product provides daily AOD at 1km.
  const collectionName = 'MODIS/061/MCD19A2_GRANULES';
  const band = 'Optical_Depth_055';

  // Function to acquire, mask, and reduce data for a given period
  async function getMeanAOD(startDate, endDate, geometry) {
    let collection = ee.ImageCollection(collectionName)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .select([band, 'AOD_QA']);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { mean: null, count: 0, images: 0 };
    }

    // Function to mask pixels based on the AOD_QA band.
    // We keep only the best quality pixels (QA flag bits 1-3 == 000).
    const maskAOD = function(image) {
      const qa = image.select('AOD_QA');
      // Extract bits 1-3 for quality, which should be 0 for best quality.
      const quality = qa.bitwiseAnd(14).eq(0); // 14 is binary 00001110
      // Scale factor for AOD is 0.001
      return image.select(band).multiply(0.001).updateMask(quality);
    };

    const maskedCollection = collection.map(maskAOD);

    // Create a single mean composite image
    const meanImage = maskedCollection.mean();

    // Calculate the mean value and the number of valid pixels
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    const mean = stats.get(band + '_mean').getInfo();
    const count = stats.get(band + '_count').getInfo();

    return { mean: mean, count: count, images: collectionSize };
  }

  // 2. Data Acquisition and Processing
  const data2019 = await getMeanAOD(startDate2019, endDate2019, wuhan);
  const data2020 = await getMeanAOD(startDate2020, endDate2020, wuhan);

  // 3. Validation and Evidence
  if (data2019.images === 0 || data2020.images === 0) {
    console.log(`Images found for Feb 2019: ${data2019.images}`);
    console.log(`Images found for Feb 2020: ${data2020.images}`);
    console.log("Evidence: One or both periods had no images available.");
    console.log("A");
    return;
  }

  console.log(`Feb 2019 - Images: ${data2019.images}, Valid Pixels: ${data2019.count}, Mean AOD: ${data2019.mean ? data2019.mean.toFixed(3) : 'N/A'}`);
  console.log(`Feb 2020 - Images: ${data2020.images}, Valid Pixels: ${data2020.count}, Mean AOD: ${data2020.mean ? data2020.mean.toFixed(3) : 'N/A'}`);

  if (data2019.count === 0 || data2020.count === 0) {
    console.log("Evidence: No valid (clear-sky) pixels after cloud masking for one/both periods.");
    console.log("A");
    return;
  }

  if (data2019.mean === null || data2020.mean === null) {
      console.log("Evidence: Calculation failed, resulting in a null value for mean AOD.");
      console.log("C3");
      return;
  }

  // 4. Final Answer
  // The question is 'Was the PM2.5 higher over Wuhan, China in February 2020 than in February 2019?'
  // Since AOD is a proxy, lower AOD implies lower PM2.5.
  // The data indicates AOD was lower in 2020, so PM2.5 was likely lower.
  // Therefore, the answer to "was it higher?" is No.
  if (data2020.mean > data2019.mean) {
    console.log("Evidence: Mean AOD (proxy for PM2.5) was higher in Feb 2020 than Feb 2019.");
    console.log("A");
  } else {
    console.log("Evidence: Mean AOD (proxy for PM2.5) was NOT higher in Feb 2020 than Feb 2019.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
